// ExternalSearchDemandPopulationKind separates provider search-interest,
// advertiser-planning, ranked-trend, and weighted-index populations. They can
// share aggregate machinery without sharing a denominator or authority.
type ExternalSearchDemandPopulationKind string

const (
	ExternalSearchInterestPopulation         ExternalSearchDemandPopulationKind = "search-interest"
	ExternalSearchHistoricalVolumePopulation ExternalSearchDemandPopulationKind = "historical-search-volume"
	ExternalSearchRankedTrendPopulation      ExternalSearchDemandPopulationKind = "ranked-trend"
	ExternalSearchKeywordPlanningPopulation  ExternalSearchDemandPopulationKind = "advertiser-keyword-planning"
	ExternalSearchProviderIndexPopulation    ExternalSearchDemandPopulationKind = "provider-weighted-index"
	ExternalSearchProviderPopulation         ExternalSearchDemandPopulationKind = "provider-defined"
)

// ExternalSearchDemandRecordKind identifies the product returned by a search
// demand surface. A provider-generated idea and a forecast are not observed
// search records even when both carry search-volume-looking fields.
type ExternalSearchDemandRecordKind string

const (
	ExternalSearchInterestSeriesRecord   ExternalSearchDemandRecordKind = "interest-time-series"
	ExternalSearchRegionalInterestRecord ExternalSearchDemandRecordKind = "regional-interest"
	ExternalSearchRankedTrendRecord      ExternalSearchDemandRecordKind = "ranked-trend-list"
	ExternalSearchKeywordIdeaRecord      ExternalSearchDemandRecordKind = "keyword-idea-set"
	ExternalSearchHistoricalMetricRecord ExternalSearchDemandRecordKind = "historical-keyword-metrics"
	ExternalSearchTrafficForecastRecord  ExternalSearchDemandRecordKind = "traffic-forecast"
	ExternalSearchProviderRecord         ExternalSearchDemandRecordKind = "provider-defined"
)

// ExternalSearchDemandSubjectKind keeps an exact typed term distinct from a
// provider topic, category, or generated suggestion. SubjectRef is opaque so
// potentially sensitive term text can remain in a governed payload.
type ExternalSearchDemandSubjectKind string

const (
	ExternalSearchExactTermSubject        ExternalSearchDemandSubjectKind = "exact-search-term"
	ExternalSearchProviderTopicSubject    ExternalSearchDemandSubjectKind = "provider-topic"
	ExternalSearchProviderCategorySubject ExternalSearchDemandSubjectKind = "provider-category"
	ExternalSearchGeneratedIdeaSubject    ExternalSearchDemandSubjectKind = "provider-generated-keyword-idea"
	ExternalSearchProviderSubject         ExternalSearchDemandSubjectKind = "provider-defined"
)

// ExternalSearchDemandRepresentationKind describes what a numeric series or
// result set means. In particular, a normalized interest index is not an
// absolute count and an advertiser forecast is not an observed search fact.
type ExternalSearchDemandRepresentationKind string

const (
	ExternalSearchSampledNormalizedInterest  ExternalSearchDemandRepresentationKind = "sampled-normalized-interest"
	ExternalSearchConsistentlyScaledInterest ExternalSearchDemandRepresentationKind = "consistently-scaled-interest"
	ExternalSearchApproximateHistoricalCount ExternalSearchDemandRepresentationKind = "approximate-historical-count"
	ExternalSearchWeightedProviderIndex      ExternalSearchDemandRepresentationKind = "provider-weighted-index"
	ExternalSearchRankedTruncatedList        ExternalSearchDemandRepresentationKind = "ranked-truncated-list"
	ExternalSearchProviderSuggestion         ExternalSearchDemandRepresentationKind = "provider-generated-suggestion"
	ExternalSearchConfigurationForecast      ExternalSearchDemandRepresentationKind = "configuration-dependent-forecast"
	ExternalSearchRepresentationUnknown      ExternalSearchDemandRepresentationKind = "unknown"
)

