type StreamDiscoverer interface {
	Discover(context.Context, PortBinding) ([]StreamDescriptor, error)
}

type PullReader interface {
	Read(context.Context, ReadRequest) (Page[Observation], error)
}

type PushReceiver interface {
	Receive(context.Context, PushDelivery) (PushReceipt, error)
}

type ChangeReconciler interface {
	Reconcile(context.Context, PortBinding, *Cursor, TimeWindow) (Page[Tombstone], error)
}

type ManualImporter interface {
	PreviewImport(context.Context, PortBinding, CollectionPlan, BlobID) ([]Observation, error)
	CommitImport(context.Context, PortBinding, CollectionPlan, BlobID, string) (CollectionRun, error)
}

type Canonicalizer interface {
	Normalize(context.Context, NormalizationRequest) (SourceItemCandidate, error)
}
